<script setup lang="ts">
import {localize} from './localization';

import {computed,ref,watch,inject} from 'vue';
import ToolIcon from './ToolIcon.vue';
import MaskEditor from './MaskEditor.vue';
import {useSession} from './store';
import {mapPiece,piecePath,pointBounds} from '../../../packages/pattern/edit';
import type {Calibration,Piece} from '../../../packages/schema/index';
import {referenceScene} from './modules/reference-scene';
const props=defineProps<{language:'zh'|'en';library?:boolean;targetId?:string;selection?:{markingId:string;pieceId:string}}>();
const emit=defineEmits<{unwrap:[];select:[id:string]}>(),store=useSession(),zh=computed(()=>props.language==='zh'),advanced=inject('advancedMode',ref(false));
const references=computed(()=>store.data.project?.references??[]),scene=computed(()=>referenceScene(references.value));
const activeId=ref(''),reference=computed(()=>references.value.find(r=>r.id===activeId.value)??references.value[0]);
const mode=ref<'pan'|'select'|'calibrate'|'color'|'pen'|'lasso'>('pan'),marker=ref<'a'|'b'>('a'),overlay=ref(true);
const calibration=ref<Calibration>({a:{x:0,y:100},b:{x:0,y:0},distanceMm:1800}),seed=ref<{x:number;y:number}>(),tolerance=ref(40),fitCurves=ref(false),fitToleranceMm=ref(.5);
const run=computed(()=>store.data.project?.referenceRun?.referenceId===reference.value?.id?store.data.project.referenceRun:undefined);
watch(()=>props.targetId,id=>{const region=store.data.project?.patternLibrary?.find(r=>r.piece.id===id);if(region)activeId.value=region.referenceId;else if(references.value.some(r=>r.id===id))activeId.value=id??'';},{immediate:true});
watch(()=>JSON.stringify([reference.value?.id,reference.value?.calibration]),()=>{const r=reference.value;if(r)calibration.value=structuredClone(JSON.parse(JSON.stringify(r.calibration??{a:{x:r.width/2,y:r.height},b:{x:r.width/2,y:0},distanceMm:1800})));seed.value=undefined;marker.value='a';},{immediate:true});
const calibrationValid=computed(()=>{const c=calibration.value;return Number.isFinite(c.distanceMm)&&c.distanceMm>0&&c.distanceMm<=100000&&Math.hypot(c.a.x-c.b.x,c.a.y-c.b.y)>1e-6;});
const fitValid=computed(()=>!advanced.value||!fitCurves.value||(Number.isFinite(fitToleranceMm.value)&&fitToleranceMm.value>=.01&&fitToleranceMm.value<=.5));
const calibrationDirty=computed(()=>JSON.stringify(calibration.value)!==JSON.stringify(reference.value?.calibration));
function pick(point:{x:number;y:number}){if(mode.value==='calibrate'){calibration.value[marker.value]=point;marker.value=marker.value==='a'?'b':'a';}else if(mode.value==='color')seed.value=point;}
async function calibrate(){const p=store.data.project,r=reference.value;if(p&&r&&calibrationValid.value)await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'reference.calibrate',referenceId:r.id,calibration:JSON.parse(JSON.stringify(calibration.value))}));}
function accepted(){seed.value=undefined;emit('select',(props.library?store.data.project?.patternLibrary?.at(-1)?.piece.id:store.data.project?.pieces.at(-1)?.id)??'');}
async function segment(){const p=store.data.project,r=reference.value;if(p&&r&&fitValid.value&&seed.value&&!calibrationDirty.value&&Number.isFinite(tolerance.value)&&tolerance.value>=0&&tolerance.value<=442)if(await store.run(()=>window.fpcad.segmentReference(p.id,p.revision,r.id,{x:seed.value!.x,y:seed.value!.y},tolerance.value,undefined,advanced.value&&fitCurves.value?fitToleranceMm.value:undefined,props.library??false)))accepted();}
async function accept(){const p=store.data.project;if(p&&await store.run(()=>window.fpcad.acceptReference(p.id,p.revision,props.library)))emit('select',(props.library?store.data.project?.patternLibrary?.at(-1)?.piece.id:store.data.project?.pieces.at(-1)?.id)??'');}
function path(piece:Piece,referenceId:string){const c=references.value.find(r=>r.id===referenceId)?.calibration;if(!c)return '';const dx=c.b.x-c.a.x,dy=c.b.y-c.a.y;return piecePath(mapPiece(piece,p=>({xMm:c.a.x+(-dy*p.xMm+dx*p.yMm)/c.distanceMm,yMm:-(c.a.y+(dx*p.xMm+dy*p.yMm)/c.distanceMm)})));}
const focusBox=computed(()=>{const region=store.data.project?.patternLibrary?.find(r=>r.piece.id===props.targetId),frame=scene.value.frames.find(f=>f.reference.id===region?.referenceId);if(!region||!frame||!frame.reference.calibration)return undefined;const c=frame.reference.calibration,dx=c.b.x-c.a.x,dy=c.b.y-c.a.y;const pixel=mapPiece(region.piece,p=>({xMm:frame.x+c.a.x+(-dy*p.xMm+dx*p.yMm)/c.distanceMm,yMm:frame.y+c.a.y+(dx*p.xMm+dy*p.yMm)/c.distanceMm}));const b=pointBounds([...pixel.nodes,...(pixel.holes??[]).flat(),...(pixel.curves??[]).flatMap(c=>[c.c1,c.c2])]);const pad=Math.max(16,Math.max(b.maxX-b.minX,b.maxY-b.minY)*.25);return `${b.minX-pad} ${b.minY-pad} ${b.maxX-b.minX+pad*2} ${b.maxY-b.minY+pad*2}`;});
function choose(id:string,referenceId:string){activeId.value=referenceId;emit('select',id);}
</script>
<template><section v-if="reference" class="references-panel" aria-label="原图标定与选区工作区">
 <div class="workspace-heading"><strong>{{zh?'原图工作区':localize('Original image workspace')}}</strong><label><input v-model="overlay" type="checkbox">{{zh?'显示花纹轮廓':localize('Show outlines')}}</label><span>{{scene.width}} × {{scene.height}} px</span></div>
 <div class="image-editing-layout"><div class="image-tools" role="toolbar" :aria-label="zh?'原图工具':localize('Image tools')"><button v-for="item in ([['pan','手形平移','Pan'],['select','选择花纹 / 节点','Select marking / node'],['calibrate','两点标定','Calibrate'],['pen','钢笔选区','Pen'],['lasso','自由套索','Lasso'],['color','按颜色选取','Color selection']] as const)" :key="item[0]" :disabled="store.busy" :aria-pressed="mode===item[0]" :class="{active:mode===item[0]}" :aria-label="zh?item[1]:localize(item[2])" :title="zh?item[1]:localize(item[2])" @click="mode=item[0]"><ToolIcon :name="item[0]"/></button></div><div class="image-editing-content">
 <p class="tool-help" role="status">{{mode==='pan'?(zh?'拖动原图平移，滚轮缩放。选择左侧工具后即可标定、选取或绘制。':localize('Drag to pan; scroll to zoom. Choose a tool to edit.')):mode==='select'?(zh?'点击原图花纹可选中，点击路径节点可调整。':localize('Click a marking or a path node to select it.')):mode==='calibrate'?(zh?`在同一角色上依次点击已知距离的两个端点。下一点：${marker==='a'?'起点':'终点'}。`:'Click two endpoints of a known distance on the same subject.'):mode==='color'?(zh?'点击原图中的目标颜色，再确认加入花纹库。':localize('Click a color, then confirm to add it to the library.')):(zh?'在原图上绘制；闭合后仍可拖动节点，点击确认才计算选区。':localize('Draw on the original; close and edit nodes, then confirm to calculate.'))}}</p>
 <fieldset v-if="mode==='calibrate'" :disabled="store.busy" class="tool-options"><label>{{zh?'两点真实距离（mm）':localize('Distance between points (mm)')}}<input v-model.number="calibration.distanceMm" aria-label="标定真实距离" type="number" min=".01" max="100000"></label><button :disabled="!calibrationValid" @click="calibrate">{{zh?'保存标定':localize('Save calibration')}}</button><small>{{zh?'例如实际 10 cm，输入 100。保存会更新已有花纹尺寸并移除其旧贴附；锁定贴附会阻止修改。':localize('For 10 cm, enter 100. Saving updates source sizes and removes their placements; locked placements block changes.')}}</small></fieldset>
 <fieldset v-if="mode==='color'" :disabled="store.busy" class="tool-options"><label>{{zh?'相近颜色范围':localize('Color similarity range')}}<input v-model.number="tolerance" type="range" min="0" max="442" aria-label="颜色容差">{{tolerance}}<small>{{zh?'越大包含越多相近颜色。':localize('Higher includes more similar colors.')}}</small></label><button :disabled="!seed||calibrationDirty||!reference.calibration||!fitValid" @click="segment">{{zh?'确认颜色选区并加入花纹库':localize('Confirm color selection and add to library')}}</button><template v-if="advanced"><label><input v-model="fitCurves" type="checkbox">{{zh?'自定义曲线拟合':localize('Custom curve fitting')}}</label><label v-if="fitCurves">{{zh?'轮廓允许偏差（mm）':localize('Outline tolerance (mm)')}}<input v-model.number="fitToleranceMm" type="number" min=".01" max=".5" step=".01"></label></template></fieldset>
 <p v-if="calibrationDirty" class="warning">{{zh?'标定尚未保存，先保存标定再生成花纹。':localize('Save calibration before generating markings.')}}</p>
 <MaskEditor :library="library" :calibration-dirty="calibrationDirty" :focus-box="focusBox" @accepted="accepted" :reference="reference" :scene="scene" :run="run" :mode="mode" :language="language" @mode="mode=$event" @reference="activeId=$event" @pick="pick"><template #overlay>
  <g v-for="f in scene.frames" :key="f.reference.id" :transform="`translate(${f.x} ${f.y})`">
   <path v-for="r in (store.data.project?.patternLibrary??[]).filter(r=>r.referenceId===f.reference.id&&(overlay||targetId===r.piece.id))" :key="r.piece.id" :d="path(r.piece,r.referenceId)" :data-source-region-id="r.piece.id" :data-selected="targetId===r.piece.id" :fill="targetId===r.piece.id?'var(--accent)':'transparent'" fill-opacity=".15" stroke="var(--accent)" :stroke-width="targetId===r.piece.id?3:.8" fill-rule="evenodd" vector-effect="non-scaling-stroke" :pointer-events="mode==='select'?'all':'none'" @pointerdown.stop="choose(r.piece.id,r.referenceId)"/>
   <path v-if="run&&f.reference.id===reference.id" :d="(run.pieces??[run.piece]).map(p=>path(p,reference.id)).join(' ')" fill="var(--accent)" fill-opacity=".12" fill-rule="evenodd" stroke="var(--accent)" vector-effect="non-scaling-stroke" pointer-events="none"/>
   <g v-if="mode==='calibrate'&&f.reference.id===reference.id" pointer-events="none"><line :x1="calibration.a.x" :y1="calibration.a.y" :x2="calibration.b.x" :y2="calibration.b.y" stroke="var(--danger)" vector-effect="non-scaling-stroke"/><circle v-for="(p,i) in [calibration.a,calibration.b]" :key="i" :cx="p.x" :cy="p.y" r="5" fill="var(--danger)"/></g>
  </g>
 </template></MaskEditor>
 <section v-if="run&&!run.accepted" class="reference-candidate"><strong>{{zh?'选区候选':localize('Selection candidate')}} · {{run.pieces?.length??1}} {{zh?'个花纹':localize('markings')}}</strong><p>{{zh?'检查轮廓后接受到花纹库。未接受的候选不会成为正式花纹。':localize('Review the outline and accept it into the library.')}}</p><p v-if="run.discardedPixels">{{zh?'已忽略孤立小像素，请检查细节：':localize('Small isolated pixels excluded; review details: ')}}{{run.discardedPixels}}</p><button v-if="!run.accepted" :disabled="store.busy" @click="accept">{{zh?'接受到花纹库':localize('Accept to marking library')}}</button><span v-else>{{zh?'已接受':localize('Accepted')}}</span></section>
</div></div></section></template>
<style scoped>.references-panel{padding:20px;min-width:0}.workspace-heading,.image-tools,.tool-options{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.workspace-heading{margin-bottom:12px}.workspace-heading span{margin-left:auto;color:var(--text-muted);font-size:12px}.image-editing-layout{display:grid;grid-template-columns:44px minmax(0,1fr);gap:12px;align-items:start}.image-editing-content{min-width:0}.image-tools{flex-direction:column;flex-wrap:nowrap;position:sticky;top:12px;padding:5px;background:var(--panel);border:1px solid var(--border);border-radius:5px}.image-tools button{width:34px;height:36px;padding:6px;display:grid;place-items:center}.image-tools .active{background:var(--selected);border-color:var(--accent)}.tool-options{border:0;padding:12px 0;margin:0}.tool-options input[type=number]{max-width:140px}.tool-options small{display:block;color:var(--text-muted)}.tool-help{font-size:13px;line-height:1.7;color:var(--text-muted)}.reference-candidate{border-top:1px solid var(--border);padding-top:12px}</style>
